/* edges details for region "systems", loaded on demand by atlas/app.js (ATLAS.loadDetails). */
window.ATLAS.addDetails("systems.edges",{"edges":{
"activation-energy:enzymes":{"type":"application","label":{"zh":"生物版的催化剂","en":"The biological catalyst"},"reason":{"zh":"酶降低反应的活化能，使反应在体温下就能很快进行。","en":"An enzyme lowers a reaction's activation energy so it runs quickly at body temperature."},"source":"../biology/cells/enzymes/#step0"},
"activation-energy:feedback":{"type":"connection","label":{"zh":"温度对速率的正反馈","en":"Temperature feeding back on rate"},"reason":{"zh":"放热反应让温度升高、速率变快，可能自我加速，是反馈的化学例子。","en":"An exothermic reaction warms itself and speeds up, a chemical example of positive feedback."},"source":"../chemistry/reactions/activation-energy/#step4"},
"activation-energy:montecarlo":{"type":"connection","label":{"zh":"只有分布的尾部起作用","en":"Only the tail of a distribution matters"},"reason":{"zh":"反应速率由能量分布尾部那一小部分分子决定，估计稀有事件需要大量样本。","en":"The rate is set by the small tail of the energy distribution, and estimating a rare event takes a very large sample."},"source":"../chemistry/reactions/activation-energy/#step1"},
"attention-mechanism:llm-sampling":{"type":"connection","label":{"zh":"同一个 softmax","en":"the same softmax"},"reason":{"zh":"注意力权重和下一词概率都由 softmax 得到；温度相当于第 1 步锐度 β 的倒数。","en":"Attention weights and next-word probabilities both come from softmax; temperature acts as the inverse of the sharpness β in the attention page's step 1."},"source":"../computing/ml/llm-sampling/#step1"},
"backpropagation:gradient-descent":{"type":"application","label":{"zh":"为梯度下降提供梯度","en":"supplies gradients to gradient descent"},"reason":{"zh":"梯度下降需要每个参数的梯度才能沿反方向更新，反向传播就是计算这些梯度的方法；本页第 3 步把两者接在一起。","en":"Gradient descent needs each parameter's gradient to step the opposite way, and backpropagation is how those gradients are computed; step 3 joins the two."},"source":"../computing/ml/backpropagation/#step3"},
"boost:feedback":{"type":"application","label":{"zh":"用测量调节占空比","en":"uses measurements to adjust duty"},"reason":{"zh":"实际稳压器可测量输出并调节占空比；本课只解释此接口，不模拟控制器。","en":"A real regulator can measure output and adjust duty; this lesson explains the connection without simulating a controller."},"source":"../physics/circuits/power-converters/#step6"},
"cell-structure:dna-replication":{"type":"application","label":{"zh":"核里的信息要靠复制传下去","en":"The nucleus's information passes on through replication"},"reason":{"zh":"细胞核管着遗传信息，信息要进下一代就得复制——细胞页的“指挥中心”，在复制页变成“复制什么、怎么保真”。","en":"The nucleus holds the genetic information, and for it to reach the next generation it must be copied — the cell page's 'command center' becomes, on the replication page, 'what is copied and how faithfully'."},"source":"../biology/cells/cell-structure/#step1"},
"convolution:cnn-feature-maps":{"type":"application","label":{"zh":"一维滑动求和 → 二维图像","en":"1-D sliding sum → 2-D images"},"reason":{"zh":"图像卷积层做的仍是“滑动窗口、对应相乘、求和”，只是窗口变成二维，且按 CNN 惯例不翻转核。","en":"An image convolution layer still does “slide a window, multiply matching entries, sum”, only in two dimensions and, by CNN convention, without flipping the kernel."},"source":"../computing/ml/cnn-feature-maps/#step0"},
"convolution:derivative":{"type":"foundation","label":{"zh":"差分就是离散导数","en":"Differences are discrete derivatives"},"reason":{"zh":"边缘核对邻居相减，算的正是离散差分；差分是导数在格点上的化身，所以边缘核天生就是导数探测器。","en":"Edge kernels subtract neighbours, computing exactly discrete differences; a difference is the derivative incarnated on a grid, so edge kernels are born derivative detectors."},"source":"../computing/ml/cnn-feature-maps/#step2"},
"convolution:freqresp":{"type":"representation","label":{"zh":"时域卷积成为频域相乘","en":"time convolution becomes frequency multiplication"},"reason":{"zh":"对零初态离散LTI系统，y=x*h；当相应变换存在时，Y(e^{iΩ})=X(e^{iΩ})H(e^{iΩ})。h绝对可和可保证稳定频率响应。Ω单位为rad/样本，不能直接当成Hz。","en":"For an initially resting discrete LTI system, y=x*h. When the transforms exist, Y(e^{iΩ})=X(e^{iΩ})H(e^{iΩ}); absolute summability of h ensures a stable frequency response. Ω is rad/sample, not directly Hz."},"source":"https://ocw.mit.edu/courses/res-6-007-signals-and-systems-spring-2011/9434f9bde960fd3b2b81de3ad442f902_MITRES_6_007S11_lec11.pdf#page=5"},
"convolution:gaussian":{"type":"connection","label":{"zh":"描述独立变量相加的分布","en":"describes distributions of independent sums"},"reason":{"zh":"独立随机变量之和的分布由卷积给出；反复相加后的正态近似需满足中心极限定理的条件。","en":"Convolution gives the distribution of a sum of independent random variables; a normal approximation after repeated sums requires central-limit conditions."},"source":"../probability/statistics/central-limit-theorem/#step5"},
"derivative:backpropagation":{"type":"application","label":{"zh":"斜率变成每个权重的梯度","en":"slopes become per-weight gradients"},"reason":{"zh":"把权重推一小步看损失变化就是割线斜率，ε 趋于 0 时成为导数；反向传播用链式法则一次算出所有这些导数。","en":"Nudging a weight and watching the loss gives a secant slope that becomes the derivative as ε → 0; backpropagation computes all these derivatives at once with the chain rule."},"source":"../computing/ml/backpropagation/#step1"},
"derivative:enzymes":{"type":"connection","label":{"zh":"曲线的斜率与渐近线","en":"Slope and asymptote of a curve"},"reason":{"zh":"米氏曲线在 [S] = 0 处斜率为 Vmax/Kₘ，在大 [S] 处趋于水平的渐近线 Vmax。","en":"The Michaelis–Menten curve has slope Vmax/Kₘ at [S] = 0 and flattens toward the asymptote Vmax at large [S]."},"source":"../biology/cells/enzymes/#step1"},
"dna-replication:probability":{"type":"connection","label":{"zh":"基因的传递与遗传学","en":"Passing genes on"},"reason":{"zh":"基因传给后代的概率，根子在分子事件里：复制保真度、突变、染色体分离方式，决定了后代拿到哪个版本——概率页的数字，正是这些分子事件的统计结果。","en":"The odds of passing a gene to offspring are rooted in molecular events: copying fidelity, mutation and how chromosomes separate decide which version offspring get — the probability lesson's numbers are the statistics of those molecular events."},"source":"../biology/cells/dna-replication/#step1"},
"embeddings:attention-mechanism":{"type":"application","label":{"zh":"输入给注意力","en":"input to attention"},"reason":{"zh":"注意力对每个词的向量做查询、键、值运算，词向量是这些运算的起点；这里只说明衔接，不涉及训练细节。","en":"Attention computes queries, keys and values from each word's vector, so embeddings are the starting point; this edge only states the hand-off and says nothing about training details."},"source":"../computing/ml/embeddings/#step4"},
"energy-pyramid:feedback":{"type":"connection","label":{"zh":"低一级的供给限制高一级的数量","en":"Supply below limits numbers above"},"reason":{"zh":"下一级提供的能量决定上一级能养活多少个体，是一种由资源供给形成的限制。","en":"The energy a level supplies caps how many individuals the level above can sustain, a resource-supply constraint."},"source":"../biology/ecology/energy-pyramid/#step2"},
"energy-pyramid:integral":{"type":"connection","label":{"zh":"年产量是速率的累积","en":"Annual production is an accumulated rate"},"reason":{"zh":"每年产量 = 生物量 × 更替率，说明某一时刻的存量与单位时间的流量是两个不同的量。","en":"Annual production = biomass × turnover, showing that a stock at one moment and a flow per unit time are different quantities."},"source":"../biology/ecology/energy-pyramid/#step3"},
"enzymes:feedback":{"type":"connection","label":{"zh":"饱和是一种非线性","en":"Saturation is a nonlinearity"},"reason":{"zh":"速率随底物浓度先线性后饱和，是系统中常见的饱和非线性，抑制剂可被视为负反馈的一个分子实现。","en":"The rate rises linearly with substrate and then saturates, a common nonlinearity in systems, and inhibitors can act as a molecular form of negative feedback."},"source":"../biology/cells/enzymes/#step4"},
"feedback:chaos-threebody":{"type":"connection","label":{"zh":"反馈会放大也会压制误差","en":"Feedback can amplify or damp errors"},"reason":{"zh":"反馈使误差按 e^{λt} 变化：λ < 0 时压制（稳定），λ > 0 时放大（混沌），是同一个指数在两种符号下的结果。","en":"Feedback makes errors evolve like e^{λt}: damped for λ < 0 (stable) and amplified for λ > 0 (chaos), the same exponent with two signs."},"source":"../physics/mechanics/chaos-threebody/#step1"},
"fourier:convolution":{"type":"connection","label":{"zh":"把卷积变为乘法","en":"turns convolution into multiplication"},"reason":{"zh":"当相应变换存在时，时域卷积对应频域乘法。本课用有限序列比较直接卷积与频域计算的结果。","en":"When the transforms exist, time-domain convolution corresponds to frequency-domain multiplication. This lesson compares direct convolution with frequency-domain computation on finite sequences."},"source":"../signal/systems/convolution/#step6"},
"graph-algorithms:shortest-path":{"type":"application","label":{"zh":"在图上按顺序展开","en":"Expanding over a graph in order"},"reason":{"zh":"图算法页用队列和栈决定访问顺序；第 1 步用“暂定距离最小者先确认”决定访问顺序，得到加权最短路。","en":"The graph-algorithms page uses a queue or stack to decide visiting order; step 1 uses “smallest tentative distance first”, which yields weighted shortest paths."},"source":"../computing/algorithms/shortest-path/#step1"},
"impulse:convolution":{"type":"application","label":{"zh":"与输入卷积得到输出","en":"convolves with input to produce output"},"reason":{"zh":"输出是各个平移冲激响应的加权和，这正是离散卷积 y[n] = Σ x[k]h[n−k]。","en":"The output sums weighted shifted impulse responses: precisely the discrete convolution y[n] = Σ x[k]h[n−k]."},"source":"../signal/systems/lti-systems/#step2"},
"impulse:freqresp":{"type":"representation","label":{"zh":"傅里叶变换给出频率响应","en":"Fourier-transforms into frequency response"},"reason":{"zh":"离散 h[n] 的离散时间傅里叶变换是 H(e^{iΩ})，Ω 单位 rad/样本；连续 h(t) 的傅里叶积分是 H(iω)，ω 单位 rad/s。变换需存在；稳定系统的绝对可和/可积是相应充分条件。不能把 δ[n] 与连续冲激直接混用。","en":"The DTFT of discrete h[n] is H(e^{iΩ}), with Ω in rad/sample; the Fourier integral of continuous h(t) is H(iω), with ω in rad/s. The transform must exist; absolute summability/integrability supplies the respective stable-system condition. A discrete unit impulse is not a continuous Dirac impulse."},"source":"https://dspguide.com/ch9/2.htm"},
"isomers:activation-energy":{"type":"connection","label":{"zh":"能垒决定能不能转","en":"The barrier decides whether it can turn"},"reason":{"zh":"单键的扭转能垒小、双键的大，e^(−ΔE/RT) 决定室温下能否越过，这就是顺反异构能分开的原因。","en":"Torsion barriers are small for single bonds and large for double bonds, and e^(−ΔE/RT) decides whether they can be crossed at room temperature, which is why cis and trans can be separated."},"source":"../chemistry/matter/isomers/#step4"},
"kalman:feedback":{"type":"application","label":{"zh":"提供用于控制的状态估计","en":"supplies state estimates for control"},"reason":{"zh":"无法直接观测的状态可先估计，再交给控制器；估计质量和模型误差会影响控制效果。","en":"Estimate states that cannot be measured directly, then pass them to a controller; estimation quality and model mismatch affect control."},"source":"../signal/control/kalman/#step6"},
"laplace:poles":{"type":"representation","label":{"zh":"揭示指数模式","en":"reveals exponential modes"},"reason":{"zh":"对本课中的有理变换，极点的实部关联增长或衰减，虚部关联振荡；还要结合因果性和收敛域判断稳定性。","en":"For the rational transforms in this lesson, pole real parts describe growth or decay and imaginary parts describe oscillation; stability also depends on causality and convergence."},"source":"../signal/transforms/laplace/#step4"},
"lti:impulse":{"type":"connection","label":{"zh":"可由冲激响应刻画","en":"is characterized by its impulse response"},"reason":{"zh":"对初始静止的 LTI 系统，把输入分解为加权、平移的单位脉冲，就能由 h 重建输出。","en":"For an initially resting LTI system, decompose the input into weighted shifted impulses and reconstruct the output from h."},"source":"../signal/systems/lti-systems/#step2"},
"lti:superposition":{"type":"connection","label":{"zh":"满足叠加性","en":"obeys superposition"},"reason":{"zh":"线性保证输入的加权组合产生相同权重的输出组合；时不变是另一项独立条件。","en":"Linearity preserves weighted combinations of input-output pairs; time invariance is a separate condition."},"source":"../signal/systems/lti-systems/#step3"},
"mechanical-energy:net-force":{"type":"connection","label":{"zh":"同一结果可以从力和能量两条路得到","en":"The same result by forces or by energy"},"reason":{"zh":"用牛顿第二定律沿轨道积分和用能量守恒得到同一个速度 √(2g(h₀ − h))，能量法不必知道轨道的形状。","en":"Integrating Newton’s second law along the track and using energy conservation give the same speed √(2g(h₀ − h)); the energy method does not need the shape of the track."},"source":"../physics/mechanics/mechanical-energy/#step1"},
"mechanism-auction:prisoners-dilemma":{"type":"connection","label":{"zh":"第二价让说真话不再吃亏","en":"Second-price makes truth-telling cost nothing"},"reason":{"zh":"第一价里人人压价藏真实价值，像囚徒困境里各自算计；第二价收第二高报价，说真话不再吃亏，规则改写了博弈的 payoff。","en":"Under first-price everyone shades their true value, calculating like prisoners in a dilemma; second-price charges the runner-up bid, so truth-telling stops costing anything — the rule rewrites the game's payoff."},"source":"../math/applied/mechanism-design/#s1"},
"momentum-collision:impulse":{"type":"representation","label":{"zh":"冲量就是动量改变多少","en":"Impulse is how much momentum changes"},"reason":{"zh":"力乘时间等于动量改变量：同样的动量要停住，时间越长平均力越小——冲量不是新量，是动量变化的另一种说法。","en":"Force times time equals the change in momentum: to stop the same momentum, more time means less average force — impulse is not a new quantity, it is the momentum change stated another way."},"source":"../physics/mechanics/momentum-collision/#step1"},
"montecarlo:dna-replication":{"type":"connection","label":{"zh":"随机变异","en":"Random variation"},"reason":{"zh":"突变是随机事件：要估计一群基因里出现某种突变的比例，就得像蒙特卡洛那样大量随机抽样、数出频率——突变页的“随机”正是抽样估计的对象。","en":"Mutations are random events: to estimate how often a given mutation shows up in a population of genes, you sample at random many times and count the frequency, Monte Carlo style — the replication lesson's 'random' is exactly what sampling estimates."},"source":"../biology/cells/dna-replication/#step4"},
"natural-selection:feedback":{"type":"connection","label":{"zh":"环境反过来塑造种群","en":"The environment shapes the population"},"reason":{"zh":"选择让种群跟随环境变化，但响应有滞后，是一阶系统跟随输入的生物版本。","en":"Selection makes the population follow the environment with a lag, a biological counterpart of a first-order system following an input."},"source":"../biology/ecology/natural-selection/#step3"},
"net-force:gravity-orbits":{"type":"application","label":{"zh":"平方反比的合力决定运动","en":"An inverse-square force decides the motion"},"reason":{"zh":"牛顿第二定律把 F = GMm/r² 变成加速度 g(r)，再用逐步积分得到轨道；轨道类型只取决于初速度。","en":"Newton’s second law turns F = GMm/r² into the acceleration g(r), and step-by-step integration gives the orbit; the type of orbit depends only on the launch speed."},"source":"../earth/astronomy/gravity-orbits/#step1"},
"ode-phase-portraits:derivative":{"type":"foundation","label":{"zh":"变化率写成方程","en":"Rates of change written as equations"},"reason":{"zh":"第 0 步把“数量每单位时间变化多少”写成 x′、y′ 的方程，是导数作为变化率的直接应用。","en":"Step 0 writes “how fast each count changes” as equations for x′ and y′, a direct use of the derivative as a rate."},"source":"../math/calculus/ode-phase-portraits/#step0"},
"ode-phase-portraits:eigen":{"type":"connection","label":{"zh":"平衡点附近可线性化","en":"Linearise near the equilibrium"},"reason":{"zh":"第 2 步找到的平衡点附近，方向场可近似为线性系统，其旋转或收敛由特征值决定。","en":"Near the equilibrium found in step 2 the field can be approximated by a linear system, whose rotation or decay is decided by eigenvalues."},"source":"../math/calculus/ode-phase-portraits/#step2"},
"oscillation:chaos-threebody":{"type":"connection","label":{"zh":"非线性系统的另一面","en":"The other side of nonlinear systems"},"reason":{"zh":"线性振动的行为规则可预测；加上非线性后，同样用微分方程描述的系统可以出现对初值极度敏感的混沌。","en":"Linear oscillation is regular and predictable; add nonlinearity and systems described by the same kind of differential equations can become chaotic, extremely sensitive to the starting point."},"source":"../physics/mechanics/chaos-threebody/#step2"},
"particles-states:water-cycle":{"type":"application","label":{"zh":"蒸发与沸腾是水循环里的两条进气路","en":"Evaporation and boiling are water's two routes into gas"},"reason":{"zh":"一杯水变干是表面少数粒子逃逸，烧开是全体挣脱成气；水循环追踪的正是同一批水在这两条路与液化之间跑。","en":"A cup drying out is a few surface particles escaping; boiling is everyone breaking free. The water cycle tracks the same water running between these two routes and liquefaction."},"source":"../chemistry/matter/particles-states/#step3"},
"poles:freqresp":{"type":"connection","label":{"zh":"影响频率响应形状","en":"shapes the frequency response"},"reason":{"zh":"当冲激响应的拉普拉斯收敛域包含虚轴时，H(iω) 给出频率响应。极点靠近虚轴可能形成尖峰，零点也会影响结果。","en":"When the Laplace region of convergence of the impulse response contains the imaginary axis, H(iω) gives frequency response. Nearby poles may produce sharp peaks; zeros also matter."},"source":"https://www.dspguide.com/CH32.PDF#page=18"},
"prisoners-dilemma:game-theory":{"type":"connection","label":{"zh":"占优策略的反例式应用","en":"A dilemma built on dominance"},"reason":{"zh":"第 0 步的收益矩阵里背叛是占优策略，却使双方都不如合作，是博弈论“占优均衡不一定最优”的经典例子。","en":"In step 0’s payoff matrix defection is dominant yet leaves both worse than cooperating, the classic case that a dominant-strategy equilibrium need not be best."},"source":"../math/applied/prisoners-dilemma/#step0"},
"prisoners-dilemma:natural-selection":{"type":"connection","label":{"zh":"得分决定谁被复制","en":"Score decides who is copied"},"reason":{"zh":"第 4 步的复制者动态让得分高的策略比例上升，与自然选择“适合度高者占比增加”是同一种数学。","en":"Step 4’s replicator dynamics let higher-scoring strategies grow in share, the same mathematics as fitter types increasing under natural selection."},"source":"../math/applied/prisoners-dilemma/#step4"},
"probability:activation-energy":{"type":"application","label":{"zh":"分子能量的概率","en":"A probability over molecular energies"},"reason":{"zh":"能量足够的分子比例就是一个概率 e^(−Eₐ/RT)，速率常数把这个概率乘上碰撞频率。","en":"The fraction of molecules with enough energy is a probability, e^(−Eₐ/RT), and the rate constant multiplies it by a collision frequency."},"source":"../chemistry/reactions/activation-energy/#step2"},
"probability:attention-mechanism":{"type":"connection","label":{"zh":"softmax 权重像一个分布","en":"softmax weights behave like a distribution"},"reason":{"zh":"softmax 输出非负且和为 1，可以读成「看每个词的比例」，熵衡量它有多集中；这是比喻性的读法，并非真实概率。","en":"Softmax outputs are non-negative and sum to 1, so they can be read as proportions of attention, with entropy measuring how concentrated they are; this is a reading aid, not a literal probability."},"source":"../computing/ml/attention-mechanism/#step1"},
"recursion-divide:binary-search":{"type":"connection","label":{"zh":"都是递归，树形不同","en":"both recursive, different tree shapes"},"reason":{"zh":"二分查找每次把规模减半并只进入一个子问题，递归树是一条链；汉诺塔缩小 1 却分成两个子问题，所以代价量级完全不同。","en":"Binary search halves the size and enters just one subproblem, so its recursion tree is a chain; Hanoi shrinks by 1 but splits into two subproblems, so its cost is of a completely different order."},"source":"../computing/algorithms/recursion-divide/#step2"},
"recursion-divide:exp-log":{"type":"application","label":{"zh":"汉诺塔的指数增长","en":"Hanoi's exponential growth"},"reason":{"zh":"汉诺塔每增加一个盘子，步数翻倍再加 1，总数是 2ⁿ−1，这是指数函数的一个具体例子；二分查找则对应对数。","en":"Each extra Hanoi disk doubles the moves and adds 1, giving 2ⁿ−1, a concrete exponential function, while binary search corresponds to the logarithm."},"source":"../computing/algorithms/recursion-divide/#step3"},
"resonance:freqresp":{"type":"representation","label":{"zh":"表现为响应峰值","en":"appears as a response peak"},"reason":{"zh":"在线性系统的频率响应幅度图上，共振表现为某段频率附近的峰；并非所有系统都有明显峰值。","en":"In a linear system’s frequency-response magnitude, resonance appears as a peak; not every system has a pronounced one."},"source":"../signal/systems/frequency-response/#step5"},
"shortest-path:pagerank":{"type":"connection","label":{"zh":"都在图上累积一个量","en":"Both accumulate a quantity over a graph"},"reason":{"zh":"最短路沿边累加权重得到距离，PageRank 沿边传递重要性；两者都是在有向/加权图上沿边做计算。","en":"Shortest paths add weights along edges to get distances while PageRank passes importance along edges; both compute along edges of a weighted or directed graph."},"source":"../computing/algorithms/shortest-path/#step5"},
"vectors:attention-mechanism":{"type":"application","label":{"zh":"向量点积打分","en":"vector dot products as scores"},"reason":{"zh":"注意力用查询向量与键向量的点积衡量相关度，点积的大小由夹角和长度共同决定。","en":"Attention scores relevance with the dot product of a query vector and key vectors; the dot product depends on both the angle and the lengths."},"source":"../computing/ml/attention-mechanism/#step0"},
"water-cycle:feedback":{"type":"application","label":{"zh":"流出量随存量增大而自我平衡","en":"Outflow grows with the stock and balances itself"},"reason":{"zh":"空气里的水越多降水越多，陆地水越多径流越多：流出与存量成正比，使各水库自动趋向稳定值，是负反馈的最简单例子。","en":"More water in the air means more rain and more on land means more runoff: outflow proportional to stock drives each reservoir toward a steady value, the simplest case of negative feedback."},"source":"../earth/climate/water-cycle/#step4"},
"work-energy:energy-pyramid":{"type":"application","label":{"zh":"能量只会被消耗，不会凭空增加","en":"Energy is spent, never created"},"reason":{"zh":"每传一级一部分变成热散失，能量金字塔上小下大是能量守恒与耗散的结果。","en":"A share is lost as heat at each step, so the energy pyramid narrows upward as a result of conservation with dissipation."},"source":"../biology/ecology/energy-pyramid/#step1"},
"work-energy:gravity-orbits":{"type":"connection","label":{"zh":"能量守恒给出逃逸速度","en":"Energy conservation gives the escape speed"},"reason":{"zh":"动能加引力势能 −GMm/r 守恒；总能量为 0 时恰好逃逸，由此得到逃逸速度 √(2GM/r)。","en":"Kinetic plus gravitational potential energy −GMm/r is conserved; a total energy of zero is the threshold of escape, which gives the escape speed √(2GM/r)."},"source":"../earth/astronomy/gravity-orbits/#step2"},
"work-energy:mechanical-energy":{"type":"application","label":{"zh":"功改变能量，摩擦做的功变成热","en":"Work changes energy; friction’s work becomes heat"},"reason":{"zh":"外力或摩擦力做的功等于能量的变化；只有重力和弹力做功时机械能守恒，摩擦做功则把机械能转为内能。","en":"The work of outside forces or friction equals the change in energy; mechanical energy is conserved when only gravity and elastic forces do work, while friction turns it into internal energy."},"source":"../physics/mechanics/mechanical-energy/#step2"}
}});
